func guardBinary(value []byte) {
	if config.MaxBinaryValueBytes > 0 && uint32(len(value)) > config.MaxBinaryValueBytes {
		panic(errRecordTooLarge)
	}
}

// Resolve returns a record either at the exact name or from the nearest valid
// ancestor (wildcard-style). Inheritance is explicit, never implicit in the
// primitive getters.
func Resolve(name string, query RecordQuery, mode ResolveMode) ResolveResult {
	canonical, err := Normalize(name)
	if err != nil {
		return ResolveResult{Requested: name}
	}
	cur := canonical
	for {
		n := resolvableName(cur)
		if n != nil {
			if val, ok := lookupRecord(n, query); ok {
				return ResolveResult{
					Found:      true,
					Requested:  canonical,
					SourceName: cur,
					Value:      val,
					Revision:   n.Revision,
					ExpiresAt:  n.ExpiresAt,
				}
			}
		}
		if mode == Exact {
			break
		}
		_, parent := splitLabel(cur)
		if parent == "" {
			break
		}
		cur = parent
	}
	return ResolveResult{Requested: canonical}
}

func lookupRecord(n *Name, q RecordQuery) ([]byte, bool) {
	switch q.Kind {
	case "address":
		if n.Records.NativeAddress != "" {
			return []byte(n.Records.NativeAddress), true
		}
	case "text":
		if v, ok := treeGet(n.Records.Text, q.Key1); ok {
			return []byte(v.(string)), true
		}
	case "coin":
		if v, ok := treeGet(n.Records.Addresses, q.Key1); ok {
			return v.([]byte), true
		}
	case "content":
		if len(n.Records.ContentHash) > 0 {
			return n.Records.ContentHash, true
		}
	case "pubkey":
		if len(n.Records.PublicKey) > 0 {
			return n.Records.PublicKey, true
		}
	case "abi":
		if v, ok := treeGet(n.Records.ABIs, q.Key1); ok {
			return v.([]byte), true
		}
	case "interface":
		if v, ok := treeGet(n.Records.Interfaces, q.Key1); ok {
			return []byte(v.(string)), true
		}
	case "record":
		if v, ok := treeGet(n.Records.Arbitrary, q.Key1+"/"+q.Key2); ok {
			return v.([]byte), true
		}
	}
	return nil, false
}

// ---------------------------------------------------------------------------
// 16. Reverse resolution and primary names
// ---------------------------------------------------------------------------

// SetPrimaryName sets the caller's primary (reverse) name. The name must be
// active and forward-resolve (Address) to the caller.
func SetPrimaryName(cur realm, name string) {
	requireNotPaused()
	c := callerUser(cur)
	canonical := mustNormalize(name)
	n := getRaw(canonical)
	if n == nil || !isActive(n) {
		panic(errNotFound)
	}
	if n.Records.NativeAddress != c.String() {
		panic(errUnauthorized)
	}
	reverse.Set(c.String(), canonical)
	emit(EvPrimaryNameChange, canonical, c, n.Owner, "")
}

// PrimaryName returns the verified primary name for an address, checking that
// (1) a reverse record exists, (2) the name is active, and (3) forward
// resolution still matches. Any failure returns not-found.
func PrimaryName(addr string) (string, bool) {
	v, ok := treeGet(reverse, addr)
	if !ok {
		return "", false
	}
	canonical := v.(string)
	n := getRaw(canonical)
	if n == nil || !isActive(n) {
		return "", false
	}
	if n.Records.NativeAddress != addr {
		return "", false
	}
	return canonical, true
}

// ClearPrimaryName clears the caller's reverse record.
func ClearPrimaryName(cur realm) {
	c := caller(cur) // allowed even when paused / during grace
	if _, removed := reverse.Remove(c.String()); removed {
		emit(EvPrimaryNameChange, "", c, "", "cleared")
	}
}

// invalidateReverseFor lazily clears a reverse record if the just-changed name
// no longer forward-verifies for the old owner. PrimaryName also re-verifies,
// so this is best-effort cleanup.
func invalidateReverseFor(oldOwner address, canonical string) {
	if v, ok := treeGet(reverse, oldOwner.String()); ok && v.(string) == canonical {
		n := getRaw(canonical)
		if n == nil || n.Records.NativeAddress != oldOwner.String() {
			reverse.Remove(oldOwner.String())
		}
	}
}

// ---------------------------------------------------------------------------
// 17. Enumeration (bounded, cursor-based)
// ---------------------------------------------------------------------------

func capLimit(limit uint16) int {
	const hardCap = 200
	if limit == 0 || int(limit) > hardCap {
		return hardCap
	}
	return int(limit)
}

// NamesByOwner lists canonical names owned by owner.
func NamesByOwner(owner string, cursor string, limit uint16) StringPage {
	prefix := owner + sep
	start := prefix
	if cursor != "" {
		start = prefix + cursor
	}
	max := capLimit(limit)
	items := []string{}
	next := ""
	byOwner.Iterate(start, prefixEnd(prefix), func(k string, v any) bool {
		if cursor != "" && k <= prefix+cursor {
			return false
		}
		if len(items) == max {
			next = strings.TrimPrefix(k, prefix)
			return true
		}
		items = append(items, v.(string))
		return false
	})
	return StringPage{Items: items, Next: next}
}

// Subnames lists direct subnames of parent.
func Subnames(parent string, cursor string, limit uint16) StringPage {
	pcanon, err := Normalize(parent)
	if err != nil {
		return StringPage{}
	}
	prefix := pcanon + sep
	start := prefix
	if cursor != "" {
		start = prefix + cursor
	}
	max := capLimit(limit)
	items := []string{}
	next := ""
	byParent.Iterate(start, prefixEnd(prefix), func(k string, v any) bool {
		if cursor != "" && k <= prefix+cursor {
			return false
		}
		if len(items) == max {
			next = strings.TrimPrefix(k, prefix)
			return true
		}
		items = append(items, v.(string))
		return false
	})
	return StringPage{Items: items, Next: next}
}

// TextKeys lists text-record keys for a name.
func TextKeys(name string, cursor string, limit uint16) StringPage {
	n := mustName(name)
	return treeKeys(n.Records.Text, cursor, limit)
}

// CoinTypes lists multichain coin types set for a name.
func CoinTypes(name string, cursor string, limit uint16) StringPage {
	n := mustName(name)
	return treeKeys(n.Records.Addresses, cursor, limit)
}

// Operators lists operators and their permissions for a name.
func Operators(name string, cursor string, limit uint16) OperatorPage {
	n := mustName(name)
	max := capLimit(limit)
	items := []OperatorView{}
	next := ""
	n.Operators.Iterate(cursor, "", func(k string, v any) bool {
		if cursor != "" && k <= cursor {
			return false
		}
		if len(items) == max {
			next = k
			return true
		}
		items = append(items, OperatorView{Address: k, Permissions: v.(Permissions)})
		return false
	})
	return OperatorPage{Items: items, Next: next}
}

func treeKeys(tree *avl.Tree, cursor string, limit uint16) StringPage {
	max := capLimit(limit)
	items := []string{}
	next := ""
	tree.Iterate(cursor, "", func(k string, v any) bool {
		if cursor != "" && k <= cursor {
			return false
		}
		if len(items) == max {
			next = k
			return true
		}
		items = append(items, k)
		return false
	})
	return StringPage{Items: items, Next: next}
}

// ---------------------------------------------------------------------------
// 18. Events
// ---------------------------------------------------------------------------

func eventKey(id uint64) string {
	// zero-pad to 20 digits for lexicographic ordering.
	s := strconv.FormatUint(id, 10)
	return strings.Repeat("0", 20-len(s)) + s
}

func recordEvent(e *Event) {
	nextEventID++
	e.ID = nextEventID
	e.Height = height()
	e.Timestamp = now()
	events.Set(eventKey(e.ID), e)
	// also surface as a native gno event for tx-level indexers.
	chain.Emit(e.Type, "name", e.Name, "actor", e.Actor, "id", strconv.FormatUint(e.ID, 10))
}

func emit(typ, name string, actor address, owner interface{}, key string) {
	ownerStr := ""
	switch o := owner.(type) {
	case address:
		ownerStr = o.String()
	case string:
		ownerStr = o
	}
	recordEvent(&Event{Type: typ, Name: name, Actor: actor.String(), Owner: ownerStr, Key: key})
}

func emitOwner(typ string, n *Name) {
	recordEvent(&Event{Type: typ, Name: n.Canonical, Actor: n.Owner.String(), Owner: n.Owner.String(), Revision: n.Revision})
}

func emitRecord(typ string, n *Name, actor address, key, newDigest string) {
	recordEvent(&Event{Type: typ, Name: n.Canonical, Actor: actor.String(), Owner: n.Owner.String(), Revision: n.Revision, Key: key, NewDigest: newDigest})
}

// EventsAfter returns events with ID strictly greater than id.
func EventsAfter(id uint64, limit uint16) EventPage {
	max := capLimit(limit)
	items := []Event{}
	next := ""
	start := eventKey(id + 1)
	events.Iterate(start, "", func(k string, v any) bool {
		if len(items) == max {
			next = k
			return true
		}
		items = append(items, *v.(*Event))
		return false
	})
	return EventPage{Items: items, Next: next}
}

// EventsForName returns events for a specific name with ID greater than after.
func EventsForName(name string, after uint64, limit uint16) EventPage {
	canonical, err := Normalize(name)
	if err != nil {
		return EventPage{}
	}
	max := capLimit(limit)
	items := []Event{}
	next := ""
	start := eventKey(after + 1)
	events.Iterate(start, "", func(k string, v any) bool {
		e := v.(*Event)
		if e.Name != canonical {
			return false
		}
		if len(items) == max {
			next = k
			return true
		}
		items = append(items, *e)
		return false
	})
	return EventPage{Items: items, Next: next}
}

// ---------------------------------------------------------------------------
// 19. Administration
// ---------------------------------------------------------------------------

func requireAdmin(cur realm) address {
	c := caller(cur)
	if c != config.Admin {
		panic(errUnauthorized)
	}
	return c
}

func requireNotPaused() {
	if config.Paused {
		panic(errPaused)
	}
}

// SetPaused toggles the global pause. Paused blocks registration, subname
// creation, transfers and record mutation; reads, renewals and primary-name
// clearing remain available. It never confiscates or mutates ownership.
func SetPaused(cur realm, paused bool) {
	requireAdmin(cur)
	config.Paused = paused
	if paused {
		emit(EvPaused, "", config.Admin, "", "")
	} else {
		emit(EvUnpaused, "", config.Admin, "", "")
	}
}

// SetRegistrationOpen toggles whether new second-level registrations are open.
func SetRegistrationOpen(cur realm, open bool) {
	requireAdmin(cur)
	config.RegistrationOpen = open
	emit(EvConfigChanged, "", config.Admin, "", "registration_open")
}

// SetPricing updates future pricing and bumps the policy revision so pending
// commitments that priced against the old rules are rejected at reveal.
func SetPricing(cur realm, pricing PricingConfig) {
	requireAdmin(cur)
	if pricing.BasePricePerSecond < 0 {
		panic(errBadRequest)
	}
	config.BasePricePerSecond = pricing.BasePricePerSecond
	if pricing.PremiumByLength != nil {
		config.PremiumByLength = pricing.PremiumByLength
	}
	if pricing.PaymentDenom != "" {
		config.PaymentDenom = pricing.PaymentDenom
	}
	config.PolicyRevision++
	emit(EvConfigChanged, "", config.Admin, "", "pricing")
}

// SetTreasury updates the treasury address.
func SetTreasury(cur realm, treasury address) {
	requireAdmin(cur)
	if !treasury.IsValid() {
		panic(errEmptyAddress)
	}
	config.Treasury = treasury
	emit(EvConfigChanged, "", config.Admin, "", "treasury")
}

// ReserveName reserves (or unreserves) an unregistered name so it cannot be
// publicly registered. Admin may not reserve an actively-owned name.
func ReserveName(cur realm, name string, reserved bool) {
	requireAdmin(cur)
	canonical := mustNormalize(name)
	n := getRaw(canonical)
	if n != nil && isActive(n) && n.Owner != (address("")) {
		panic(errNameUnavailable) // cannot confiscate an active name
	}
	if n == nil {
		label, parent := splitLabel(canonical)
		n = &Name{
			Canonical: canonical,
			Label:     label,
			Parent:    parent,
			Depth:     depthOf(canonical),
			Records:   newRecords(),
			Operators: avl.NewTree(),
			CreatedAt: now(),
		}
	}
	// If unreserving a bare placeholder (never registered), physically remove
	// it so the name becomes Available again rather than lingering as an
	// ExpiresAt==0 node (which statusOf would read as a permanent Active name).
	if !reserved && !n.Owner.IsValid() {
		names.Remove(canonical)
		emit(EvConfigChanged, canonical, config.Admin, "", "reserve")
		return
	}
	n.Reserved = reserved
	names.Set(canonical, n)
	emit(EvConfigChanged, canonical, config.Admin, "", "reserve")
}

// TransferAdmin begins a two-step admin handover.
func TransferAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !next.IsValid() {
		panic(errEmptyAddress)
	}
	config.PendingAdmin = next
	emit(EvConfigChanged, "", config.Admin, next, "transfer_admin")
}

// AcceptAdmin completes the two-step admin handover.
func AcceptAdmin(cur realm) {
	c := caller(cur)
	if config.PendingAdmin == (address("")) || c != config.PendingAdmin {
		panic(errUnauthorized)
	}
	config.Admin = c
	config.PendingAdmin = address("")
	emit(EvConfigChanged, "", c, "", "accept_admin")
}

// SetLimits updates operational storage/abuse limits (future registrations and
// mutations). Existing names are unaffected until next mutation.
func SetLimits(cur realm, maxRecords, maxOperators uint16, maxText, maxBinary uint32) {
	requireAdmin(cur)
	config.MaxRecordsPerName = maxRecords
	config.MaxOperatorsPerName = maxOperators
	config.MaxTextValueBytes = maxText
	config.MaxBinaryValueBytes = maxBinary
	emit(EvConfigChanged, "", config.Admin, "", "limits")
}

// ---------------------------------------------------------------------------
// 20. Read API (status/lookup)
// ---------------------------------------------------------------------------

// Status returns the lifecycle status of a name.
func Status(name string) NameStatus {
	canonical, err := Normalize(name)
	if err != nil {
		return StatusAvailable
	}
	return statusOf(getRaw(canonical))
}

// Exists reports whether a name currently resolves to a live registration.
func Exists(name string) bool {
	canonical, err := Normalize(name)
	if err != nil {
		return false
	}
	n := getRaw(canonical)
	if n == nil {
		return false
	}
	switch statusOf(n) {
	case StatusActive, StatusGrace:
		return true
	}
	return false
}

// OwnerOf returns the owner of an active/grace name.
func OwnerOf(name string) (string, bool) {
	canonical, err := Normalize(name)
	if err != nil {
		return "", false
	}
	n := getRaw(canonical)
	if n == nil {
		return "", false
	}
	switch statusOf(n) {
	case StatusActive, StatusGrace:
		return n.Owner.String(), true
	}
	return "", false
}

// GetName returns a read-only view of a name.
func GetName(name string) (NameView, bool) {
	canonical, err := Normalize(name)
	if err != nil {
		return NameView{}, false
	}
	n := getRaw(canonical)
	if n == nil {
		return NameView{}, false
	}
	return NameView{
		Canonical:   n.Canonical,
		Owner:       n.Owner.String(),
		Status:      string(statusOf(n)),
		CreatedAt:   n.CreatedAt,
		UpdatedAt:   n.UpdatedAt,
		ExpiresAt:   n.ExpiresAt,
		GraceEndsAt: n.GraceEndsAt,
		Parent:      n.Parent,
		Label:       n.Label,
		Depth:       n.Depth,
		TTL:         n.TTL,
		Generation:  n.Generation,
		Revision:    n.Revision,
		Reserved:    n.Reserved,
		NativeAddr:  n.Records.NativeAddress,
	}, true
}

// CommitmentStatus returns the state of a pending commitment.
func CommitmentStatus(commit string) CommitmentView {
	cm, ok := getCommitment(commit)
	if !ok {
		return CommitmentView{}
	}
	return CommitmentView{
		Exists:    true,
		Committer: cm.Committer.String(),
		CreatedAt: cm.CreatedAt,
		ReadyAt:   cm.CreatedAt + config.MinCommitAge,
		ExpiresAt: cm.CreatedAt + config.MaxCommitAge,
	}
}

// ---------------------------------------------------------------------------
// 21. Rendering
// ---------------------------------------------------------------------------

// Render is a human-readable explorer. It never mutates state.
func Render(path string) string {
	path = strings.TrimPrefix(path, "/")
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "name/"):
		return renderName(strings.TrimPrefix(path, "name/"))
	case strings.HasPrefix(path, "address/"):
		return renderAddress(strings.TrimPrefix(path, "address/"))
	case strings.HasPrefix(path, "available/"):
		return renderAvailable(strings.TrimPrefix(path, "available/"))
	case path == "events":
		return renderEvents()
	case path == "help":
		return renderHelp()
	default:
		return "# GNS\n\nUnknown route. See [/help](/r/moul/gns/v1:help).\n"
	}
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# GNS — Gno Name Service\n\n")
	b.WriteString("A single-realm, ENS-equivalent naming system for gno.land.\n\n")
	b.WriteString(ufmt.Sprintf("- Registered names: **%d**\n", names.Size()))
	b.WriteString(ufmt.Sprintf("- Events: **%d**\n", int(nextEventID)))
	b.WriteString(ufmt.Sprintf("- Registration open: **%t**\n", config.RegistrationOpen))
	b.WriteString(ufmt.Sprintf("- Paused: **%t**\n\n", config.Paused))
	b.WriteString("## Routes\n\n")
	b.WriteString("- `/name/<name>` — details for a name\n")
	b.WriteString("- `/address/<g1...>` — primary name + owned names\n")
	b.WriteString("- `/available/<name>` — availability and price\n")
	b.WriteString("- `/events` — recent events\n")
	b.WriteString("- `/help` — public API summary\n")
	return b.String()
}

func renderName(name string) string {
	canonical, err := Normalize(name)
	if err != nil {
		return "# " + name + "\n\nInvalid name: " + err.Error() + "\n"
	}
	n := getRaw(canonical)
	if n == nil {
		return "# " + canonical + "\n\n_Available._ See [/available/" + canonical + "](/r/moul/gns/v1:available/" + canonical + ").\n"
	}
	var b strings.Builder
	b.WriteString("# " + canonical + "\n\n")
	b.WriteString("Owner: `" + n.Owner.String() + "`\n\n")
	b.WriteString("Status: " + string(statusOf(n)) + "\n\n")
	if n.ExpiresAt > 0 {
		b.WriteString(ufmt.Sprintf("Expires: %s\n\n", time.Unix(n.ExpiresAt, 0).UTC().Format("2006-01-02")))
	} else {
		b.WriteString("Expires: never (permanent subname)\n\n")
	}
	b.WriteString(ufmt.Sprintf("Generation: %d · Revision: %d\n\n", int(n.Generation), int(n.Revision)))
	if n.Records.NativeAddress != "" {
		b.WriteString("Primary address: `" + n.Records.NativeAddress + "`\n\n")
	}
	// text records
	b.WriteString("## Records\n\n")
	hasText := false
	n.Records.Text.Iterate("", "", func(k string, v any) bool {
		b.WriteString("- " + k + ": " + v.(string) + "\n")
		hasText = true
		return false
	})
	if !hasText {
		b.WriteString("_No text records._\n")
	}
	// subnames
	b.WriteString("\n## Subnames\n\n")
	subs := Subnames(canonical, "", 50)
	if len(subs.Items) == 0 {
		b.WriteString("_None._\n")
	} else {
		for _, s := range subs.Items {
			b.WriteString("- " + s + "\n")
		}
	}
	return b.String()
}

func renderAddress(addr string) string {
	var b strings.Builder
	b.WriteString("# " + addr + "\n\n")
	if pn, ok := PrimaryName(addr); ok {
		b.WriteString("Primary name: **" + pn + "**\n\n")
	} else {
		b.WriteString("_No verified primary name._\n\n")
	}
	b.WriteString("## Owned names\n\n")
	page := NamesByOwner(addr, "", 50)
	if len(page.Items) == 0 {
		b.WriteString("_None._\n")
	} else {
		for _, s := range page.Items {
			b.WriteString("- " + s + "\n")
		}
	}
	return b.String()
}

func renderAvailable(name string) string {
	canonical, err := Normalize(name)
	if err != nil {
		return "# " + name + "\n\nInvalid: " + err.Error() + "\n"
	}
	var b strings.Builder
	b.WriteString("# " + canonical + "\n\n")
	if available(canonical) {
		b.WriteString("**Available.**\n\n")
		q, _ := Price(canonical, config.MinRegistrationDuration)
		b.WriteString(ufmt.Sprintf("Price for %d seconds: %d %s\n", int(config.MinRegistrationDuration), int(q.Amount), q.Denom))
	} else {
		b.WriteString("**Not available** (status: " + string(Status(canonical)) + ").\n")
	}
	return b.String()
}

func renderEvents() string {
	var b strings.Builder
	b.WriteString("# Recent events\n\n")
	from := uint64(0)
	if nextEventID > 20 {
		from = nextEventID - 20
	}
	page := EventsAfter(from, 20)
	if len(page.Items) == 0 {
		b.WriteString("_No events yet._\n")
		return b.String()
	}
	b.WriteString("| ID | Type | Name | Actor |\n| ---: | --- | --- | --- |\n")
	for _, e := range page.Items {
		b.WriteString(ufmt.Sprintf("| %d | %s | %s | `%s` |\n", int(e.ID), e.Type, e.Name, e.Actor))
	}
	return b.String()
}

func renderHelp() string {
	return "# GNS API\n\n" +
		"Read: `Normalize`, `Status`, `Exists`, `OwnerOf`, `GetName`, `Resolve`, " +
		"`Address`, `CoinAddress`, `Text`, `ContentHash`, `PublicKey`, `ABI`, " +
		"`Interface`, `Record`, `PrimaryName`, `Price`, `CommitmentStatus`, " +
		"`NamesByOwner`, `Subnames`, `TextKeys`, `CoinTypes`, `Operators`, " +
		"`EventsAfter`, `EventsForName`.\n\n" +
		"Mutations (crossing, panic on failure): `Commit`, `Register`, `Renew`, " +
		"`Transfer`, `CreateSubname`, `DeleteSubname`, `SetRegistrationPolicy`, " +
		"`LockPolicy`, `SetOperator`, `RemoveOperator`, `SetPrimaryName`, " +
		"`ClearPrimaryName`, and the typed record setters.\n\n" +
		"Admin: `SetPaused`, `SetRegistrationOpen`, `SetPricing`, `SetTreasury`, " +
		"`ReserveName`, `TransferAdmin`, `AcceptAdmin`, `SetLimits`.\n"
}

// ---------------------------------------------------------------------------
// 22. Internal storage helpers
// ---------------------------------------------------------------------------

func coins(denom string, amount int64) chain.Coins {
	return chain.NewCoins(chain.NewCoin(denom, amount))
}

// treeGet adapts the avl v0 API (Get returns a single value; existence is via
// Has) to the (value, ok) idiom used throughout this file.
func treeGet(t *avl.Tree, key string) (any, bool) {
	if !t.Has(key) {
		return nil, false
	}
	return t.Get(key), true
}

func getRaw(canonical string) *Name {
	v, ok := treeGet(names, canonical)
	if !ok {
		return nil
	}
	return v.(*Name)
}

// resolvableName returns the name only if it is currently Active (records
// resolve only for active names).
func resolvableName(name string) *Name {
	canonical, err := Normalize(name)
	if err != nil {
		return nil
	}
	n := getRaw(canonical)
	if n == nil || !isActive(n) {
		return nil
	}
	return n
}

// mustName returns an existing name or panics with not_found.
func mustName(name string) *Name {
	canonical := mustNormalize(name)
	n := getRaw(canonical)
	if n == nil {
		panic(errNotFound)
	}
	return n
}

func putName(n *Name) {
	names.Set(n.Canonical, n)
	byOwner.Set(ownerKey(n.Owner, n.Canonical), n.Canonical)
	if n.Parent != "" {
		byParent.Set(n.Parent+sep+n.Canonical, n.Canonical)
	}
}

func deleteName(n *Name) {
	n.Deleted = true
	byOwner.Remove(ownerKey(n.Owner, n.Canonical))
	if n.Parent != "" {
		byParent.Remove(n.Parent + sep + n.Canonical)
	}
	names.Remove(n.Canonical)
}

func ownerKey(owner address, canonical string) string {
	return owner.String() + sep + canonical
}

func getCommitment(key string) (*commitment, bool) {
	v, ok := treeGet(commitments, key)
	if !ok {
		return nil, false
	}
	return v.(*commitment), true
}

func getOperator(n *Name, addr address) (Permissions, bool) {
	if n.Operators == nil {
		return Permissions{}, false
	}
	v, ok := treeGet(n.Operators, addr.String())
	if !ok {
		return Permissions{}, false
	}
	return v.(Permissions), true
}

func allowlistHas(tree *avl.Tree, addr address) bool {
	v, ok := treeGet(tree, addr.String())
	return ok && v.(bool)
}

func collectPaymentDenom(cur realm, price int64, denom string, treasury address) {
	if price <= 0 {
		return
	}
	if !cur.Previous().IsUserCall() {
		panic(errNotUser)
	}
	sent := unsafe.OriginSend()
	got := sent.AmountOf(denom)
	if got < price {
		panic(errInsufficientPay)
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := cur.Address()
	if treasury != self {
		bk.SendCoins(self, treasury, coins(denom, price))
	}
	if over := got - price; over > 0 {
		bk.SendCoins(self, cur.Previous().Address(), coins(denom, over))
	}
}

func prefixEnd(prefix string) string {
	if prefix == "" {
		return ""
	}
	b := []byte(prefix)
	for i := len(b) - 1; i >= 0; i-- {
		if b[i] < 0xff {
			b[i]++
			return string(b[:i+1])
		}
	}
	return "" // prefix is all 0xff; iterate to end
}

// Package handles is a tiny on-chain nickname registry.
//
// Any address may claim one unique handle (3-20 lowercase letters/digits,
// starting with a letter), attach a short bio, transfer the handle to
// another address, or release it back to the pool. It is deliberately
// small: two AVL indexes (handle -> record, address -> record) and a
// handful of guarded mutators.
package handles

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

const maxBioLen = 140

// record is the persisted state for one claimed handle.
type record struct {
	handle   string
	owner    address
	bio      string
	sinceBlk int64
}

var (
	byHandle avl.Tree // handle (string)      -> *record
	byOwner  avl.Tree // owner address.String() -> *record
)

// validHandle reports whether h is 3-20 chars, starts with a lowercase
// letter, and contains only lowercase letters and digits thereafter.
func validHandle(h string) bool {
	if len(h) < 3 || len(h) > 20 {
		return false
	}
	for i := 0; i < len(h); i++ {
		c := h[i]
		switch {
		case c >= 'a' && c <= 'z':
		case c >= '0' && c <= '9' && i > 0:
		default:
			return false
		}
	}
	return true
}

// Register claims handle for the caller. Aborts if the handle is invalid,
// already taken, or the caller already owns a handle (release it first).
func Register(cur realm, handle string) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("only a direct user call can register a handle")
	}
	if !validHandle(handle) {
		panic("handle must be 3-20 lowercase letters/digits, starting with a letter")
	}
	caller := cur.Previous().Address()
	if byOwner.Has(caller.String()) {
		panic("this address already owns a handle; release it first")
	}
	if byHandle.Has(handle) {
		panic("handle already taken")
	}

	r := &record{
		handle:   handle,
		owner:    caller,
		sinceBlk: runtime.ChainHeight(),
	}
	byHandle.Set(handle, r)
	byOwner.Set(caller.String(), r)
	chain.Emit("HandleRegistered", "handle", handle, "owner", caller.String())
}

// SetBio updates the bio of the handle owned by the caller.
func SetBio(cur realm, bio string) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	if len(bio) > maxBioLen {
		panic("bio too long (max " + strconv.Itoa(maxBioLen) + " chars)")
	}
	r := ownRecord(cur)
	r.bio = bio
	chain.Emit("BioUpdated", "handle", r.handle)
}

// Release frees the handle owned by the caller, making it claimable again.
func Release(cur realm) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	r := ownRecord(cur)
	byHandle.Remove(r.handle)
	byOwner.Remove(r.owner.String())
	chain.Emit("HandleReleased", "handle", r.handle)
}

// Transfer moves the caller's handle to another address that does not
// already own one.
func Transfer(cur realm, to address) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	if !to.IsValid() {
		panic("invalid recipient address")
	}
	r := ownRecord(cur)
	if byOwner.Has(to.String()) {
		panic("recipient already owns a handle")
	}
	byOwner.Remove(r.owner.String())
	r.owner = to
	byOwner.Set(to.String(), r)
	chain.Emit("HandleTransferred", "handle", r.handle, "to", to.String())
}

// ownRecord resolves the record for the current caller, panicking if the
// caller does not own a handle.
func ownRecord(cur realm) *record {
	caller := cur.Previous().Address()
	v := byOwner.Get(caller.String())
	if v == nil {
		panic("this address does not own a handle")
	}
	return v.(*record)
}

// OwnerOf returns the owner of handle and whether it exists.
func OwnerOf(handle string) (address, bool) {
	v := byHandle.Get(handle)
	if v == nil {
		return address(""), false
	}
	return v.(*record).owner, true
}

// HandleOf returns the handle owned by addr, if any.
func HandleOf(addr address) (string, bool) {
	v := byOwner.Get(addr.String())
	if v == nil {
		return "", false
	}
	return v.(*record).handle, true
}

// Count returns the number of currently registered handles.
func Count() int {
	return byHandle.Size()
}

// Render renders Markdown. "/" lists every handle; "/<handle>" shows a
// single record's detail.
func Render(path string) string {
	path = strings.TrimPrefix(path, "/")
	if path == "" {
		return renderIndex()
	}
	return renderHandle(path)
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# 🪪 Handles\n\n")
	b.WriteString("A tiny on-chain nickname registry. Claim a short handle, ")
	b.WriteString("attach a bio, transfer it, or release it.\n\n")

	if byHandle.Size() == 0 {
		b.WriteString("_No handles registered yet._\n\n")
		b.WriteString("Call `Register(handle)` to claim the first one.\n")
		return b.String()
	}

	b.WriteString("| Handle | Owner | Since block |\n")
	b.WriteString("|--------|-------|-------------|\n")
	byHandle.Iterate("", "", func(key string, value interface{}) bool {
		r := value.(*record)
		b.WriteString("| [" + key + "](/" + key + ") | " + short(r.owner.String()) +
			" | " + strconv.Itoa(int(r.sinceBlk)) + " |\n")
		return false
	})
	b.WriteString("\nTotal handles: " + strconv.Itoa(byHandle.Size()) + "\n")
	return b.String()
}

func renderHandle(handle string) string {
	v := byHandle.Get(handle)
	if v == nil {
		return "# Handles\n\nNo handle named `" + handle + "`.\n\n[← all handles](/)\n"
	}
	r := v.(*record)

	var b strings.Builder
	b.WriteString("# 🪪 @" + r.handle + "\n\n")
	b.WriteString("**Owner:** " + r.owner.String() + "\n\n")
	if r.bio != "" {
		b.WriteString("**Bio:** " + r.bio + "\n\n")
	}
	b.WriteString("**Registered at block:** " + strconv.Itoa(int(r.sinceBlk)) + "\n\n")
	b.WriteString("[← all handles](/)\n")
	return b.String()
}

// short truncates a long address for the index table.
func short(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

package kudos

import (
	"chain"
	"chain/runtime/unsafe"
	"sort"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// counts maps an address (as string) -> number of kudos received.
var counts avl.Tree

// feed holds recent kudos, newest first, capped at feedCap entries.
var feed []kudo

const feedCap = 50

type kudo struct {
	from   address
	to     address
	reason string
}

// Give records a kudos from the caller to `to` with a reason.
// A caller cannot give kudos to themselves.
func Give(cur realm, to address, reason string) {
	from := unsafe.PreviousRealm().Address()
	if !to.IsValid() {
		panic("invalid recipient address")
	}
	if from == to {
		panic("cannot give kudos to yourself")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("reason must not be empty")
	}

	key := to.String()
	n := int64(0)
	if v := counts.Get(key); v != nil {
		n = v.(int64)
	}
	counts.Set(key, n+1)

	// prepend newest, cap the feed
	feed = append([]kudo{{from: from, to: to, reason: reason}}, feed...)
	if len(feed) > feedCap {
		feed = feed[:feedCap]
	}

	chain.Emit("KudosGiven", "from", from.String(), "to", to.String(), "reason", reason)
}

// entry is a leaderboard row used for deterministic sorting.
type entry struct {
	addr  string
	count int64
}

// byScore sorts by count desc, then address asc for stable ties.
type byScore []entry

func (s byScore) Len() int      { return len(s) }
func (s byScore) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byScore) Less(i, j int) bool {
	if s[i].count != s[j].count {
		return s[i].count > s[j].count
	}
	return s[i].addr < s[j].addr
}

func leaderboard() []entry {
	out := make([]entry, 0, counts.Size())
	counts.Iterate("", "", func(key string, value any) bool {
		out = append(out, entry{addr: key, count: value.(int64)})
		return false
	})
	sort.Sort(byScore(out))
	return out
}

// Render shows a leaderboard of most-received addresses and a recent feed.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Kudos\n\n")
	b.WriteString("Give props to addresses. `Give(to, reason)` records a kudos.\n\n")

	b.WriteString("## Leaderboard\n\n")
	lb := leaderboard()
	if len(lb) == 0 {
		b.WriteString("_No kudos yet._\n\n")
	} else {
		b.WriteString("| # | Address | Kudos |\n")
		b.WriteString("| --- | --- | --- |\n")
		for i, e := range lb {
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + e.addr + " | " + strconv.FormatInt(e.count, 10) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Recent kudos\n\n")
	if len(feed) == 0 {
		b.WriteString("_Nothing here yet._\n")
	} else {
		for _, k := range feed {
			b.WriteString("- " + k.from.String() + " → " + k.to.String() + ": " + k.reason + "\n")
		}
	}

	return b.String()
}

// Package rot13demo is a small gnoweb demo of the ROT13 / Caesar cipher
// provided by the [p/moul/x/daily/rot13](/p/moul/x/daily/rot13/v1) library: it
// renders an explanation, a worked ROT13 example, and interactive path-driven
// ROT13 and Caesar transforms.
//
// It contains no cipher logic of its own — everything comes from `rot13.Rot13`
// and `rot13.Caesar`. Render reads its input straight from the gnoweb path.
package rot13demo

import (
	"strconv"
	"strings"

	"gno.land/p/moul/x/daily/rot13/v1"
)

// hexNibble decodes a single hex digit, returning -1 if invalid.
func hexNibble(b byte) int {
	switch {
	case b >= '0' && b <= '9':
		return int(b - '0')
	case b >= 'a' && b <= 'f':
		return int(b-'a') + 10
	case b >= 'A' && b <= 'F':
		return int(b-'A') + 10
	}
	return -1
}

// percentDecode turns "%20"/"+" style path escapes back into readable text so
// gnoweb links with spaces or punctuation round-trip nicely. Invalid escapes
// are left verbatim.
func percentDecode(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '+':
			sb.WriteByte(' ')
		case c == '%' && i+2 < len(s):
			hi, lo := hexNibble(s[i+1]), hexNibble(s[i+2])
			if hi >= 0 && lo >= 0 {
				sb.WriteByte(byte(hi<<4 | lo))
				i += 2
			} else {
				sb.WriteByte(c)
			}
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

// Render is the gnoweb entry point (not a crossing call).
//
//	Render("")                 -> explanation + a worked example
//	Render("/Hello, Gno!")     -> the input and its ROT13
//	Render("/caesar/3/attack") -> a Caesar shift of 3 applied to "attack"
func Render(path string) string {
	p := strings.TrimPrefix(path, "/")

	// Caesar sub-path: /caesar/<shift>/<text>
	if rest, ok := strings.CutPrefix(p, "caesar/"); ok {
		shiftStr, text, found := strings.Cut(rest, "/")
		if !found {
			return renderRoot() + "\n> Usage: `/caesar/<shift>/<text>` — e.g. `/caesar/3/attack%20at%20dawn`\n"
		}
		shift, err := strconv.Atoi(shiftStr)
		if err != nil {
			return renderRoot() + "\n> `" + shiftStr + "` is not a valid integer shift.\n"
		}
		text = percentDecode(text)
		return renderCaesar(text, shift)
	}

	if p == "" {
		return renderRoot()
	}

	return renderRot13(percentDecode(p))
}

func renderRoot() string {
	var sb strings.Builder
	sb.WriteString("# ROT13\n\n")
	sb.WriteString("Demo of the [`p/moul/x/daily/rot13`](/p/moul/x/daily/rot13/v1) library — ")
	sb.WriteString("an on-chain port of Go's classic **ROT13** cipher, the standard-library ")
	sb.WriteString("`strings.Map` / `io.Reader` teaching example. Each ASCII letter is rotated ")
	sb.WriteString("13 places through the alphabet; everything else is left alone.\n\n")
	sb.WriteString("Because the alphabet has 26 letters and 13 is exactly half, **ROT13 is its ")
	sb.WriteString("own inverse** — encoding twice returns the original text.\n\n")

	const demo = "Hello, Gno!"
	enc := rot13.Rot13(demo)
	sb.WriteString("## Example\n\n")
	sb.WriteString("| stage | text |\n|---|---|\n")
	sb.WriteString("| input | `" + demo + "` |\n")
	sb.WriteString("| ROT13 | `" + enc + "` |\n")
	sb.WriteString("| ROT13 again | `" + rot13.Rot13(enc) + "` |\n\n")

	sb.WriteString("## Try it\n\n")
	sb.WriteString("- `Render(\"/Uryyb, Tab!\")` — decode any text (append it to the path).\n")
	sb.WriteString("- `Render(\"/caesar/3/attack at dawn\")` — a general Caesar shift.\n\n")
	sb.WriteString("Or call the library functions directly:\n\n")
	sb.WriteString("```go\n")
	sb.WriteString("rot13.Rot13(\"Hello, Gno!\")     // " + strconv.Quote(enc) + "\n")
	sb.WriteString("rot13.Caesar(\"attack\", 3)      // " + strconv.Quote(rot13.Caesar("attack", 3)) + "\n")
	sb.WriteString("rot13.Caesar(\"Hello\", 13)      // same as Rot13: " + strconv.Quote(rot13.Caesar("Hello", 13)) + "\n")
	sb.WriteString("```\n")
	return sb.String()
}

func renderRot13(text string) string {
	enc := rot13.Rot13(text)
	var sb strings.Builder
	sb.WriteString("# ROT13\n\n")
	sb.WriteString("| stage | text |\n|---|---|\n")
	sb.WriteString("| input | `" + text + "` |\n")
	sb.WriteString("| ROT13 | `" + enc + "` |\n\n")
	sb.WriteString("_ROT13 is its own inverse — running it on the output above gives back the input._\n\n")
	sb.WriteString("[Back to overview](/r/moul/x/daily/rot13demo/v1:)\n")
	return sb.String()
}

func renderCaesar(text string, shift int) string {
	enc := rot13.Caesar(text, shift)
	var sb strings.Builder
	sb.WriteString("# Caesar shift " + strconv.Itoa(shift) + "\n\n")
	sb.WriteString("| stage | text |\n|---|---|\n")
	sb.WriteString("| input | `" + text + "` |\n")
	sb.WriteString("| shifted | `" + enc + "` |\n\n")
	sb.WriteString("_Decode with the opposite shift: `/caesar/" + strconv.Itoa(-shift) + "/...`._\n\n")
	sb.WriteString("[Back to overview](/r/moul/x/daily/rot13demo/v1:)\n")
	return sb.String()
}

// Package timecapsule is a public guestbook where every message is sealed
// until a future block height, then permanently unlocked for anyone to read.
package timecapsule

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

type capsule struct {
	id           int64
	author       address
	message      string
	createdAt    int64
	unlockHeight int64
}

var (
	capsules avl.Tree // key: zero-padded id -> *capsule
	nextID   int64
)

const (
	maxDelayBlocks int64 = 1_000_000
	maxMessageLen  int   = 500
)

// Leave seals a new message that stays hidden until `delayBlocks` blocks
// from now, then becomes publicly readable forever. Returns the capsule id.
func Leave(cur realm, message string, delayBlocks int64) int64 {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls can leave a capsule")
	}

	message = strings.TrimSpace(message)
	if message == "" {
		panic("message must not be empty")
	}
	if len(message) > maxMessageLen {
		panic("message too long")
	}
	if delayBlocks <= 0 || delayBlocks > maxDelayBlocks {
		panic("delayBlocks out of range")
	}

	now := runtime.ChainHeight()
	id := nextID
	nextID++

	c := &capsule{
		id:           id,
		author:       cur.Previous().Address(),
		message:      message,
		createdAt:    now,
		unlockHeight: now + delayBlocks,
	}
	capsules.Set(idKey(id), c)

	chain.Emit("CapsuleSealed",
		"id", strconv.FormatInt(id, 10),
		"unlockHeight", strconv.FormatInt(c.unlockHeight, 10),
	)
	return id
}

func idKey(id int64) string {
	s := strconv.FormatInt(id, 10)
	return strings.Repeat("0", 12-len(s)) + s
}

func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case path == "sealed":
		return renderSealed()
	case strings.HasPrefix(path, "capsule/"):
		return renderCapsule(strings.TrimPrefix(path, "capsule/"))
	default:
		return "> [!WARNING]\n> Path not found\n"
	}
}

func renderHome() string {
	now := runtime.ChainHeight()

	revealed := 0
	sealed := 0
	capsules.Iterate("", "", func(_ string, value any) bool {
		if value.(*capsule).unlockHeight <= now {
			revealed++
		} else {
			sealed++
		}
		return false
	})

	var out strings.Builder
	out.WriteString("# ⏳ Time Capsule Guestbook\n\n")
	out.WriteString("Leave a message for the future. It stays sealed until its unlock block height, then anyone can read it — call `Leave(message, delayBlocks)`.\n\n")
	out.WriteString(strconv.Itoa(revealed+sealed) + " capsule(s) total · " +
		strconv.Itoa(revealed) + " unlocked · " + strconv.Itoa(sealed) + " still sealed")
	if sealed > 0 {
		out.WriteString(" (see [sealed](sealed))")
	}
	out.WriteString(".\n\n## Unlocked messages\n\n")

	if revealed == 0 {
		out.WriteString("_None yet. Be the first to leave one that will open later._\n")
		return out.String()
	}

	capsules.Iterate("", "", func(_ string, value any) bool {
		c := value.(*capsule)
		if c.unlockHeight <= now {
			out.WriteString(renderEntry(c))
		}
		return false
	})
	return out.String()
}

func renderSealed() string {
	now := runtime.ChainHeight()

	var out strings.Builder
	out.WriteString("# Sealed Capsules\n\n")

	found := false
	capsules.Iterate("", "", func(_ string, value any) bool {
		c := value.(*capsule)
		if c.unlockHeight > now {
			found = true
			out.WriteString("- capsule [#" + strconv.FormatInt(c.id, 10) + "](capsule/" +
				strconv.FormatInt(c.id, 10) + ") by `" + c.author.String() +
				"` — unlocks at block " + strconv.FormatInt(c.unlockHeight, 10) +
				" (" + strconv.FormatInt(c.unlockHeight-now, 10) + " blocks left)\n")
		}
		return false
	})
	if !found {
		out.WriteString("_No sealed capsules right now._\n")
	}
	return out.String()
}

func renderCapsule(idStr string) string {
	id, err := strconv.ParseInt(idStr, 10, 64)
	if err != nil {
		return "> [!WARNING]\n> Invalid capsule id\n"
	}
	v := capsules.Get(idKey(id))
	if v == nil {
		return "> [!WARNING]\n> Capsule not found\n"
	}
	c := v.(*capsule)
	now := runtime.ChainHeight()

	var out strings.Builder
	out.WriteString("# Capsule #" + strconv.FormatInt(c.id, 10) + "\n\n")
	out.WriteString("Sealed by `" + c.author.String() + "` at block " + strconv.FormatInt(c.createdAt, 10) + ".\n\n")

	if c.unlockHeight > now {
		out.WriteString("\U0001f512 Still sealed. Unlocks at block " + strconv.FormatInt(c.unlockHeight, 10) +
			" (" + strconv.FormatInt(c.unlockHeight-now, 10) + " blocks left).\n")
		return out.String()
	}

	out.WriteString("\U0001f513 Unlocked at block " + strconv.FormatInt(c.unlockHeight, 10) + ":\n\n> " +
		sanitize.InlineText(c.message) + "\n")
	return out.String()
}

func renderEntry(c *capsule) string {
	return "- **#" + strconv.FormatInt(c.id, 10) + "** by `" + c.author.String() +
		"` (sealed at block " + strconv.FormatInt(c.createdAt, 10) +
		", opened at block " + strconv.FormatInt(c.unlockHeight, 10) + "):\n  > " +
		sanitize.InlineText(c.message) + "\n\n"
}

// Package toposortdemo is a small gnoweb demo of the dependency ordering
// provided by the [p/moul/x/daily/toposort](/p/moul/x/daily/toposort/v1)
// library: it shows a build graph resolved into a safe install order, and a
// deliberately broken graph to show how a cycle is reported.
//
// It contains no ordering logic of its own — the graph, the sort and the cycle
// detection all come from the library. Stateless and read-only, so Render is
// fully deterministic.
package toposortdemo

import (
	"strconv"
	"strings"

	"gno.land/p/moul/x/daily/toposort/v1"
)

// buildGraph is a small, realistic dependency graph: a realm on top of a couple
// of libraries, themselves on a shared core.
func buildGraph() *toposort.Graph {
	return toposort.FromPairs([][2]string{
		{"realm", "ui"},
		{"realm", "storage"},
		{"ui", "markdown"},
		{"storage", "avl"},
		{"markdown", "strings"},
		{"avl", "strings"},
	})
}

// cyclicGraph is broken on purpose: auth and session need each other.
func cyclicGraph() *toposort.Graph {
	return toposort.FromPairs([][2]string{
		{"server", "auth"},
		{"auth", "session"},
		{"session", "auth"},
	})
}

// Render renders the demo for gnoweb.
//
//	Render("")       / Render("/") -> the build graph, resolved
//	Render("/cycle")               -> the broken graph and its report
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Topological Sort\n\n")
	b.WriteString("Ordering a dependency graph so nothing is built before what it needs, ")
	b.WriteString("demoing the [`p/moul/x/daily/toposort`](/p/moul/x/daily/toposort/v1) library.\n\n")

	if parseArg(path) == "cycle" {
		return b.String() + renderCycle()
	}

	g := buildGraph()
	b.WriteString("## The graph\n\n```\n")
	b.WriteString(g.String())
	b.WriteString("```\n\n")

	order, err := g.Sort()
	if err != nil {
		b.WriteString("_Unexpectedly cyclic._\n")
		return b.String()
	}
	b.WriteString("## Install order\n\n")
	for i, n := range order {
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(". `")
		b.WriteString(n)
		b.WriteString("`\n")
	}
	b.WriteString("\nTies are broken lexicographically, so this ordering is the ")
	b.WriteString("*only* one the library will ever produce for this graph.\n\n")
	b.WriteString("> See [`/cycle`](/r/moul/x/daily/toposortdemo/v1:cycle) for what happens ")
	b.WriteString("when the graph is not a DAG.\n")
	return b.String()
}

// renderCycle shows the failure mode.
func renderCycle() string {
	g := cyclicGraph()
	var b strings.Builder
	b.WriteString("## A graph with a cycle\n\n```\n")
	b.WriteString(g.String())
	b.WriteString("```\n\n")

	order, err := g.Sort()
	if err == nil {
		b.WriteString("_Unexpectedly acyclic._\n")
		return b.String()
	}
	b.WriteString("`Sort` returns an error: **")
	b.WriteString(err.Error())
	b.WriteString("**\n\n")
	b.WriteString("Ordered before giving up: ")
	if len(order) == 0 {
		b.WriteString("_nothing_")
	} else {
		b.WriteString("`" + strings.Join(order, "`, `") + "`")
	}
	b.WriteString("\n\nStuck on the cycle: `")
	b.WriteString(strings.Join(g.CycleNodes(), "`, `"))
	b.WriteString("`\n\n> The nodes still stuck are named rather than silently dropped, ")
	b.WriteString("so a caller can report exactly which dependencies are tangled.\n")
	return b.String()
}

// parseArg extracts the first path segment.
func parseArg(path string) string {
	s := strings.TrimSpace(path)
	s = strings.TrimPrefix(s, "/")
	if i := strings.IndexByte(s, '/'); i >= 0 {
		s = s[:i]
	}
	return s
}

